function topologicalSort(numNodes, edges) {
  const graph = Array.from({length:numNodes},()=>[]);
  const inDegree = new Array(numNodes).fill(0);

  for (const [u,v] of edges) {
    graph[u].push(v); // u must come before v
    inDegree[v]++;
  }

  const queue = [];
  for (let i=0;i<numNodes;i++) if (inDegree[i]===0) queue.push(i);

  const result = [];
  let head=0;
  while (head < queue.length) {
    const node = queue[head++];
    result.push(node);
    for (const nb of graph[node]) {
      inDegree[nb]--;
      if (inDegree[nb]===0) queue.push(nb); // dependency satisfied
    }
  }

  if (result.length !== numNodes) return []; // cycle detected
  return result;
}

function canFinish(numCourses, prerequisites) {
  return topologicalSort(numCourses, prerequisites).length === numCourses;
}
